// Definimos el HTML completo dentro de las comillas invertidas
const miCodigoHtml = `
<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>Control Remoto IoT</title>
    <style>
        /* ESTILOS */
        body { background-color: #0d1117; color: #c9d1d9; font-family: 'Courier New', monospace; text-align: center; padding: 20px; display: flex; flex-direction: column; justify-content: center; min-height: 100vh; margin: 0; }
        h1 { color: #58a6ff; text-shadow: 0 0 10px rgba(88, 166, 255, 0.5); font-size: 24px; margin-bottom: 10px;}
        p { font-size: 14px; opacity: 0.8; margin-bottom: 30px; }

        /* BOTONES */
        .iot-btn { display: block; width: 100%; padding: 25px; margin-bottom: 20px; font-size: 18px; font-weight: bold; text-transform: uppercase; border: none; border-radius: 12px; cursor: pointer; transition: all 0.2s ease; box-shadow: 0 4px 6px rgba(0,0,0,0.3); }
        .iot-btn:active { transform: scale(0.95); }

        /* COLORES Y ANIMACIÓN */
        .btn-welcome { background: linear-gradient(135deg, #2ea043 0%, #238636 100%); color: white; border: 2px solid #3fb950; }
        .btn-alert { background: linear-gradient(135deg, #da3633 0%, #b62324 100%); color: white; border: 2px solid #f85149; animation: pulse 2s infinite; }

        @keyframes pulse { 
            0% { box-shadow: 0 0 0 0 rgba(218, 54, 51, 0.4); } 
            70% { box-shadow: 0 0 0 15px rgba(218, 54, 51, 0); } 
            100% { box-shadow: 0 0 0 0 rgba(218, 54, 51, 0); } 
        }

        /* CONSOLA */
        #console-log { margin-top: 20px; background: #161b22; border: 1px solid #30363d; border-radius: 6px; padding: 10px; font-size: 12px; color: #8b949e; text-align: left; min-height: 40px; }
        .success { color: #3fb950 !important; border-color: #3fb950 !important; }
        .error { color: #f85149 !important; border-color: #f85149 !important; }
    </style>
</head>
<body>

    <h1>🏠 SMART HOME CONTROL</h1>
    <p>Conectado al servidor: {{TEACHER_NAME}}<br>Estado: EN LÍNEA 🟢</p>

    <button class="iot-btn btn-welcome" onclick="sendCommand('bienvenida')">🔔 TIMBRE / BIENVENIDA</button>
    <button class="iot-btn btn-alert" onclick="sendCommand('alerta')">🚨 ACTIVAR ALARMA 🚨</button>

    <div id="console-log">> Esperando comando...</div>

    <script>
        // *** URL DEL WEBHOOK ***
        const WEBHOOK_URL = '{{WEBHOOK_BASE_URL}}/webhook/recibir-accion'; 

        async function sendCommand(actionType) {
            const logDiv = document.getElementById('console-log');

            // 1. Feedback Visual Inmediato (Usando suma de texto para no romper el código)
            logDiv.innerHTML = '> Enviando paquete de datos: <strong>' + actionType.toUpperCase() + '</strong>...';

            // 2. Feedback Táctil (Vibración)
            if (navigator.vibrate) navigator.vibrate(50); 

            try {
                const response = await fetch(WEBHOOK_URL, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ 
                        action: actionType,
                        device: 'mobile_student',
                        timestamp: new Date().toISOString()
                    })
                });

                if (response.ok) {
                    // ÉXITO: Mensaje verde y vibración doble
                    logDiv.innerHTML = '> COMANDO RECIBIDO EN SERVIDOR ✅<br>> Acción ejecutada: ' + actionType;
                    logDiv.className = 'success'; // Cambia el color del texto a verde
                    if (navigator.vibrate) navigator.vibrate([100, 50, 100]); 
                } else {
                    throw new Error('Error en el servidor');
                }

            } catch (error) {
                // ERROR: Mensaje rojo y vibración larga
                logDiv.innerHTML = '> ERROR DE CONEXIÓN ❌<br>> Revisa tu internet.';
                logDiv.className = 'error';
                if (navigator.vibrate) navigator.vibrate(500); 
            }
        }
    </script>
</body>
</html>
`;

// Retornamos el paquete listo para el siguiente nodo
return [
  {
    json: {
      paginaparaqr: miCodigoHtml
    }
  }
];

const dashboardHtml = `
    <!DOCTYPE html>
    <html>
    <head>
        <title>SISTEMA DE MONITOREO</title>
        <style>
            body { background: #000; color: #0f0; font-family: monospace; display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100vh; overflow: hidden; margin: 0; }

            /* RADAR ANIMADO */
            .radar { width: 200px; height: 200px; border: 2px solid #0f0; border-radius: 50%; position: relative; box-shadow: 0 0 20px #0f0; background: radial-gradient(circle, transparent 60%, rgba(0,255,0,0.2)); }
            .radar::after { content: ''; position: absolute; top: 50%; left: 50%; width: 50%; height: 2px; background: #0f0; transform-origin: 0 0; animation: scan 2s linear infinite; }
            @keyframes scan { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

            h1 { margin-top: 30px; text-shadow: 0 0 10px #0f0; }
            #log { margin-top: 20px; color: #555; font-size: 12px; }

            /* ESTADO DE ALERTA */
            .alert-mode { background: #200 !important; color: #f00 !important; }
            .alert-mode .radar { border-color: #f00; box-shadow: 0 0 50px #f00; }
            .alert-mode .radar::after { background: #f00; animation-duration: 0.5s; }

            /* BOTON INICIAL */
            #init-btn { position: absolute; top:0; left:0; width:100%; height:100%; background: rgba(0,0,0,0.95); z-index:99; display:flex; flex-direction:column; align-items:center; justify-content:center; font-size:24px; cursor:pointer; color: white; text-align: center; padding: 20px;}
            .pulse-text { animation: pulse 1.5s infinite; color: #0f0; font-weight: bold; margin-top: 20px;}
            @keyframes pulse { 0% { opacity: 0.5; } 50% { opacity: 1; } 100% { opacity: 0.5; } }
        </style>
    </head>
    <body>

        <div id="init-btn" onclick="iniciar()">
            <div>INICIAR SISTEMA DE VIGILANCIA</div>
            <div class="pulse-text">CLICK AQUÍ PARA HABILITAR AUDIO</div>
        </div>

        <div class="radar" id="radar-visual"></div>
        <h1 id="status">SISTEMA SEGURO</h1>
        <div id="log">Esperando conexión satelital...</div>

        <audio id="snd-alerta" src="https://actions.google.com/sounds/v1/alarms/alarm_clock.ogg"></audio>
        <audio id="snd-bienvenida" src="https://actions.google.com/sounds/v1/alarms/mechanical_clock_ring.ogg"></audio>

        <script>
            // *** URL (Apunta al Webhook de CONSULTA) ***
            const URL_CONSULTA = '{{WEBHOOK_BASE_URL}}/webhook/consultar-estado'; 

            // Variables de control
            let stopTimer = null;
            let tiempoBloqueoVisual = 0; // Para mantener el color rojo unos segundos extra

            function iniciar() {
                document.getElementById('init-btn').style.display = 'none';
                // Desbloqueo silencioso
                const a1 = document.getElementById('snd-alerta');
                const a2 = document.getElementById('snd-bienvenida');
                a1.volume = 0; a2.volume = 0;
                a1.play().then(() => { a1.pause(); a1.currentTime=0; a1.volume=1; });
                a2.play().then(() => { a2.pause(); a2.currentTime=0; a2.volume=1; });

                // Intervalo de 3 segundos (seguro para Google Sheets)
                setInterval(consultarNube, 3000); 
            }

            // --- CONTROLADOR DE AUDIO ---
            function reproducirControlado(idAudio) {
                const alerta = document.getElementById('snd-alerta');
                const bienvenida = document.getElementById('snd-bienvenida');
                const target = document.getElementById(idAudio);

                // Detener todo
                alerta.pause(); alerta.currentTime = 0;
                bienvenida.pause(); bienvenida.currentTime = 0;
                if (stopTimer) clearTimeout(stopTimer);

                // Play
                target.play().catch(e => console.log("Error play:", e));

                // Cortar a los 4 segundos
                stopTimer = setTimeout(() => {
                    target.pause();
                    target.currentTime = 0;
                }, 4000);
            }

            async function consultarNube() {
                try {
                    const res = await fetch(URL_CONSULTA);
                    const data = await res.json();

                    const radar = document.getElementById('radar-visual');
                    const texto = document.getElementById('status');
                    const body = document.body;

                    // Debug visual
                    document.getElementById('log').innerText = "Ultimo escaneo: " + new Date().toLocaleTimeString();

                    if (data.sonar == 1) {
                        // --- MODO ALARMA ---
                        texto.innerText = "⚠️ INTRUSO DETECTADO ⚠️";
                        body.classList.add('alert-mode');
                        reproducirControlado('snd-alerta');

                        // Bloqueamos el reseteo visual por 5 segundos (4s del audio + 1s extra)
                        tiempoBloqueoVisual = Date.now() + 5000;
                    } 
                    else if (data.sonar == 2) {
                        // --- MODO BIENVENIDA ---
                        texto.innerText = "🔔 VISITANTE EN PUERTA";
                        body.classList.remove('alert-mode'); 
                        reproducirControlado('snd-bienvenida');

                        // Bloqueamos el reseteo visual por 5 segundos
                        tiempoBloqueoVisual = Date.now() + 5000;
                    } 
                    else {
                        // --- MODO SILENCIO ---
                        // Solo reseteamos a verde si YA PASÓ el tiempo de bloqueo
                        if (Date.now() > tiempoBloqueoVisual) {
                            texto.innerText = "SISTEMA SEGURO";
                            body.classList.remove('alert-mode');
                        }
                        // Si no ha pasado el tiempo, no hacemos nada (se queda en rojo/alerta)
                    }
                } catch (e) { 
                    console.log("Conectando..."); 
                }
            }
        </script>
    </body>
    </html>
`;

return [{ json: { html_profe: dashboardHtml } }];
